#if CONTROLLER_RX_ISO_PROBE
#include "hci_dump.h"

static uint32_t rx_iso_count;
static uint32_t rx_iso_errors;
static uint16_t rx_iso_length;
static uint8_t rx_iso_packet[34];

static void rx_dump_reset(void) {}
static void rx_dump_message(int level, const char *format, va_list args) {
    (void)level;
    (void)format;
    (void)args;
}
static void rx_dump_packet(uint8_t type, uint8_t in, uint8_t *packet, uint16_t length) {
    if (type == HCI_EVENT_PACKET && in == 1 && length && packet[0] == HCI_EVENT_HARDWARE_ERROR) ++rx_iso_errors;
    if (type != 5 || in != 1) return;
    ++rx_iso_count;
    if (rx_iso_count == 1) {
        rx_iso_length = length;
        if (length == sizeof(rx_iso_packet)) memcpy(rx_iso_packet, packet, length);
    }
    printf("RX_ISO packet=05");
    for (size_t i = 0; i < length; ++i) printf("%02x", packet[i]);
    printf(" length=%u count=%lu\n", length, (unsigned long)rx_iso_count);
}
static const hci_dump_t rx_dump = {rx_dump_reset, rx_dump_packet, rx_dump_message};
#endif

